\noindent {\bf A two-phase RSG ($2$-RSG) method}
\begin{itemize}
\item [] {\bf Input:}
Initial point $x_1$, number of runs $S$, iteration limit $N$, and sample size $T$.
\item [] {\bf Optimization phase:}
\item [] \hspace{0.1in} For $s = 1, \ldots, S$
\begin{itemize}
	\item [] Call the RSG method with input $x_1$,
iteration limit $N$, stepsizes $\{\gamma_k\}$ in \eqnok{constant_step} and
probability mass function $P_{R}$ in \eqnok{prob_fun}. Let $\bar x_s$ be
the output of this procedure.
\end{itemize}
\item [] {\bf Post-optimization phase:}
\item[] \hspace{0.1in} Choose a solution $\bar x^*$ from the candidate
list $\{\bar x_1, \ldots, \bar x_S\}$ such that
\beq
\|g(\bar x^*)\| = \min_{s = 1, \ldots, S} \|g(\bar x_s)\|, \ \
g(\bar x_s) := \frac{1}{T} \sum_{k=1}^T G(\bar x_s, \xi_k),
\eeq
where $G(x, \xi_k)$, $k = 1, \ldots, T$, are the stochastic gradients
returned by the $\SFO$.
\end{itemize}

\noindent {\bf A two-phase RSGF ($2$-RSGF) method}
\begin{itemize}
\item [] {\bf Input:}
Initial point $x_1$, number of runs $S$, iteration limit $N$, and sample size $T$.
\item [] {\bf Optimization phase:}
\item [] \hspace{0.1in} For $s = 1, \ldots, S$
	\begin{itemize}
	\item [] Call the RSGF method with input $x_1$,
iteration limit $N$, stepsizes $\{\gamma_k\}$ in \eqnok{zero_constant_step},
probability mass function $P_{R}$ in \eqnok{prob_fun2}, and the smoothing parameter
$\mu$ satisfying \eqnok{def_mu}. Let $\bar x_s$ be
the output of this procedure.
\end{itemize}
\item [] {\bf Post-optimization phase:}
\item[] \hspace{0.1in} Choose a solution $\bar x^*$ from the candidate
list $\{\bar x_1, \ldots, \bar x_S\}$ such that
\beq
\|g_{\mu}(\bar x^*)\| = \min_{s = 1, \ldots, S} \|g_{\mu}(\bar x_s)\|, \ \
g_{\mu}(\bar x_s) := \frac{1}{T} \sum_{k=1}^T G_{\mu}(\bar x_s, \xi_k, u_k),
\eeq
where $G_\mu(x, \xi, u)$ is defined in \eqnok{grad_free_def}.
\end{itemize}

{\bf Optimization phase:}
\item [] \hspace{0.1in} For $s = 1, \ldots, S$
\begin{itemize}
	\item [] Call the RSG method with input $x_1$,
iteration limit $N$, stepsizes $\{\gamma_k\}$ in \eqnok{constant_step} and
probability mass function $P_{R}$ in \eqnok{prob_fun}. Let $\bar x_s$ be
the output of this procedure.
\end{itemize}

